package com.studenthub.controller;
import com.fasterxml.jackson.databind.ObjectMapper;import com.studenthub.dao.PrivateMessageDAO;import com.studenthub.model.*;import com.studenthub.util.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet(name="SendPrivateMessageServlet",urlPatterns="/messages/send") @MultipartConfig(maxFileSize=UploadPolicy.VIDEO_MAX,maxRequestSize=UploadPolicy.MULTIPART_MAX)
public class SendPrivateMessageServlet extends HttpServlet{private final PrivateMessageDAO dao=new PrivateMessageDAO();private final ObjectMapper json=new ObjectMapper();@Override protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException,jakarta.servlet.ServletException{q.setCharacterEncoding("UTF-8");if(!CsrfToken.isValid(q)){r.sendError(403);return;}long conversation;try{conversation=Long.parseLong(q.getParameter("conversationId"));}catch(Exception e){r.sendError(400);return;}String content=q.getParameter("message");AttachmentRequest.Result file=AttachmentRequest.read(q.getPart("attachment"));if(!file.valid()){getServletContext().log("Private upload rejected: VALIDATION_FAILED");jsonError(r,400,file.error());return;}if((content==null||content.isBlank())&&file.upload()==null){jsonError(r,400,"Type a message or choose an attachment.");return;}try{PrivateMessage m=dao.send(conversation,(Long)q.getSession().getAttribute("userId"),q.getParameter("clientMessageId"),content,file.upload());Map<String,Object> out=new LinkedHashMap<>();out.put("messageId",m.messageId());out.put("conversationId",m.conversationId());out.put("senderId",m.senderId());out.put("message",m.message()==null?"":m.message());out.put("createdLabel",m.getCreatedLabel());out.put("status",m.getStatus());Attachment a=m.attachment();if(a!=null){out.put("attachmentId",a.attachmentId());out.put("originalFilename",a.originalFilename());out.put("mimeType",a.mimeType());out.put("fileSize",a.fileSize());out.put("attachmentType",a.isImage()?"IMAGE":a.isVideo()?"VIDEO":a.isAudio()?"AUDIO":"FILE");String url=q.getContextPath()+"/messages/attachments/"+a.attachmentId();out.put("previewUrl",url);out.put("downloadUrl",url+"?download=1");}r.setContentType("application/json");r.setCharacterEncoding("UTF-8");json.writeValue(r.getWriter(),out);}catch(SecurityException e){AttachmentRequest.discard(file.upload());getServletContext().log("Private upload rejected: UNAUTHORIZED");r.sendError(403);}catch(IllegalArgumentException e){AttachmentRequest.discard(file.upload());jsonError(r,400,e.getMessage());}catch(Exception e){AttachmentRequest.discard(file.upload());getServletContext().log("Private upload failed: DB_INSERT_FAILED, "+e.getClass().getName());jsonError(r,500,"Failed to send");}}private void jsonError(HttpServletResponse r,int status,String message)throws IOException{r.setStatus(status);r.setContentType("application/json");json.writeValue(r.getWriter(),Map.of("error",message));}}
